INSERT INTO articles(title,slug,seo_title,meta_description,content_html,status,published_at) VALUES
('如何保护个人网络隐私','protect-online-privacy','如何保护个人网络隐私：从设置到习惯','从账户、浏览器和网络连接三个方面，建立可持续的隐私保护习惯。','<p>网络隐私不是把自己完全隐藏，而是理解哪些数据会被收集，并主动做出选择。保护隐私通常从少量、持续的设置开始。</p><h2>先整理账户权限</h2><p>检查不常用应用的权限，关闭不必要的位置、通讯录和麦克风访问。为不同服务使用独立密码，并开启多重验证。</p><h2>减少不必要的暴露</h2><p>在公开页面发布信息前，考虑它是否会暴露联系方式、行程或身份线索。定期清理不再使用的账户。</p><h2>总结</h2><p>隐私保护是一个过程。定期更新设备、检查权限和学习服务的隐私政策，比追求某个“万能工具”更可靠。</p>','published',NOW()),
('公共 Wi-Fi 安全吗','public-wifi-safety','公共 Wi-Fi 安全吗？连接前后要注意什么','公共 Wi-Fi 方便但并不天然可信，了解风险并采取基本措施可以降低暴露。','<p>公共 Wi-Fi 的名称不一定代表网络的真实运营者，开放网络上的通信也可能面临窃听或钓鱼风险。</p><h2>连接前检查</h2><p>确认网络名称，避免连接无密码或名称相似的热点。关闭自动加入网络功能。</p><h2>使用时保护账户</h2><p>优先访问使用 HTTPS 的网站，不在陌生网络中处理高风险事务。完成后忘记该网络并关闭共享设置。</p><h2>结论</h2><p>公共网络可以用于低风险浏览，但不要把它当作可信的家庭网络。</p>','published',NOW()),
('如何防止个人信息泄露','prevent-personal-data-leaks','如何防止个人信息泄露：实用检查清单','从密码、权限、社交工程和数据备份四个方面减少个人信息泄露风险。','<p>信息泄露往往来自多个小疏忽的叠加。建立检查清单可以帮助我们更早发现问题。</p><h2>保护登录凭据</h2><p>使用密码管理器生成独立密码，开启双重身份验证，不通过聊天工具发送验证码。</p><h2>识别可疑请求</h2><p>任何要求立即付款、提供验证码或安装远程控制软件的请求，都应通过官方渠道重新核实。</p><h2>定期复盘</h2><p>检查账户登录记录和已授权应用，删除不认识的会话与权限。</p>','published',NOW()),
('什么是端到端加密','what-is-end-to-end-encryption','什么是端到端加密？用简单语言理解','端到端加密让消息在发送端加密，并尽量只由接收端解密。','<p>端到端加密的核心是：服务传输消息时不能直接读取消息内容。它并不意味着设备、联系人或元数据都完全隐身。</p><h2>它保护什么</h2><p>在实现正确且设备安全的前提下，它可以降低传输过程中内容被读取的风险。</p><h2>它不能解决什么</h2><p>如果设备被恶意软件控制，或者用户主动把内容分享给他人，加密不会消除这些风险。</p><p>阅读服务官方说明，了解备份和密钥验证机制。</p>','published',NOW()),
('如何创建安全密码','create-strong-passwords','如何创建安全密码：避免重复使用','学习创建长且独立的密码，并用多重验证进一步保护账户。','<p>安全密码的重点不是复杂到无法记住，而是长度足够、每个服务独立且不包含容易猜到的个人信息。</p><h2>推荐做法</h2><p>使用密码管理器生成随机密码；无法使用时，使用不重复的长密码短语。</p><h2>不要这样做</h2><p>不要在多个网站重复密码，不要使用生日、手机号或连续字符，也不要把密码写在公开可见的位置。</p>','published',NOW()),
('双重身份验证有什么用','two-factor-authentication-guide','双重身份验证有什么用？设置方法与注意事项','双重身份验证可以在密码泄露后增加一道独立的账户保护。','<p>双重身份验证要求登录者提供密码之外的第二种证明，例如验证器代码、安全密钥或设备确认。</p><h2>如何选择</h2><p>在服务支持时，优先考虑安全密钥或验证器应用，并保存恢复代码。</p><h2>注意恢复流程</h2><p>恢复邮箱和手机号同样需要保护。不要把验证码告诉任何人。</p>','published',NOW()),
('什么是 VPN 及其工作原理','what-is-vpn','什么是 VPN 及其工作原理','了解 VPN 隧道、加密和服务商角色，理性判断 VPN 的适用范围。','<p>VPN 通常在设备与 VPN 服务器之间建立加密连接，使网络流量通过该服务器转发。</p><h2>VPN 能做什么</h2><p>它可以在不可信网络中增加传输保护，并改变网站看到的出口地址。</p><h2>VPN 不能保证什么</h2><p>VPN 不会自动阻止钓鱼、恶意软件或所有在线追踪。服务商本身也需要被信任。</p>','published',NOW()),
('VPN 和代理服务器有什么区别','vpn-vs-proxy','VPN 和代理服务器有什么区别？','比较 VPN 和代理在覆盖范围、加密和使用场景上的差异。','<p>代理通常为特定应用或协议转发请求，而 VPN 更常在系统或网络层建立隧道。</p><h2>如何选择</h2><p>先明确目标：如果只是测试特定应用的出口，代理可能足够；如果需要保护设备到服务器之间的多种流量，应阅读 VPN 的实现说明。</p><p>无论使用哪种工具，都要选择透明、信誉良好的服务。</p>','published',NOW()),
('如何选择安全的网络连接','choose-secure-network-connection','如何选择安全的网络连接','从加密、身份验证、设备更新和网络分离等方面检查连接安全。','<p>安全连接不仅取决于信号强弱，还取决于网络是否可信、通信是否加密以及设备配置是否合理。</p><h2>家庭网络</h2><p>更新路由器固件，使用强管理密码，关闭不必要的远程管理。</p><h2>移动场景</h2><p>优先使用移动数据或可信热点，公共网络中避免处理敏感事务。</p>','published',NOW()),
('网络钓鱼攻击如何识别','identify-phishing-attacks','网络钓鱼攻击如何识别？','掌握钓鱼邮件、短信和网页的常见信号，减少误点击。','<p>钓鱼攻击借助紧迫感、权威身份或奖励诱惑，让人交出凭据或执行危险操作。</p><h2>检查链接</h2><p>不要只看链接显示文字，检查真实域名；遇到登录要求时，手动打开官方应用或书签。</p><h2>验证请求</h2><p>通过独立渠道联系对方，不使用消息中的电话号码或链接。</p>','published',NOW()),
('如何保护手机上的个人数据','protect-mobile-data','如何保护手机上的个人数据','通过锁屏、系统更新、权限管理和备份降低手机数据风险。','<p>手机集中保存照片、联系人、支付和通信信息，因此应把它当作重要的个人设备来管理。</p><h2>基础设置</h2><p>使用可靠的锁屏方式，及时更新系统和应用，关闭不需要的通知预览。</p><h2>应用权限</h2><p>定期检查定位、相机、麦克风和文件访问权限，删除长期不用的应用。</p>','published',NOW()),
('什么是 DNS 泄露','what-is-dns-leak','什么是 DNS 泄露？如何理解和检查','DNS 请求可能透露访问的域名，了解解析路径有助于判断网络隐私风险。','<p>DNS 负责把域名转换为 IP 地址。即使其他流量经过加密隧道，如果 DNS 请求仍由外部网络处理，也可能暴露查询信息。</p><h2>检查思路</h2><p>查看设备当前使用的 DNS 服务器，并结合工具服务商的公开说明进行验证。</p><p>不要仅凭一次检测下结论，网络环境和客户端配置可能影响结果。</p>','published',NOW()),
('如何检查网络连接安全性','check-network-security','如何检查网络连接安全性','一份适合普通用户的网络连接安全检查步骤。','<p>检查连接安全时，可以从网络身份、加密状态、设备配置和异常表现四方面开始。</p><h2>基本步骤</h2><p>确认网络名称，检查 HTTPS，更新设备，查看是否开启了不必要的共享。发现证书警告时不要强行继续。</p><h2>记录异常</h2><p>记录时间、设备和现象，必要时联系网络管理员或服务商。</p>','published',NOW()),
('Windows 网络安全设置指南','windows-network-security-settings','Windows 网络安全设置指南','介绍 Windows 用户可以检查的账户、更新、防火墙和应用权限。','<p>Windows 的安全设置应保持系统更新、账户权限最小化，并使用系统自带的安全防护功能。</p><h2>更新与防火墙</h2><p>安装来自官方渠道的系统更新，保持防火墙开启，不要为了运行未知程序而长期关闭安全功能。</p><h2>应用来源</h2><p>优先使用可信来源，安装前检查发布者和权限。</p>','published',NOW()),
('数据加密为什么重要','why-data-encryption-matters','数据加密为什么重要？','理解静态数据和传输数据加密如何降低信息被读取的风险。','<p>加密把可读信息转换为需要密钥才能还原的形式，是保护数据机密性的重要技术。</p><h2>两种常见场景</h2><p>传输加密保护设备之间的通信，存储加密保护设备或服务器上的数据。两者都需要正确的密钥管理。</p><p>加密不能替代访问控制、备份和恶意软件防护。</p>','published',NOW()),
('如何安全地使用公共网络','safe-public-network-use','如何安全地使用公共网络','在机场、酒店和咖啡店使用公共网络时的安全实践。','<p>公共网络的便利性伴随身份不确定和配置不可控的问题。</p><h2>使用前</h2><p>关闭文件共享和自动连接，确认热点名称。设备和应用应完成更新。</p><h2>使用后</h2><p>退出账户，忘记网络，检查是否安装了陌生证书或应用。</p>','published',NOW()),
('什么是 HTTPS 及其作用','what-is-https','什么是 HTTPS 及其作用？','了解 HTTPS 如何保护浏览器与网站之间的传输。','<p>HTTPS 使用 TLS 保护浏览器和网站之间的通信，并通过证书帮助浏览器验证网站身份。</p><h2>看见锁形图标不代表一切安全</h2><p>HTTPS 保护的是连接，不代表网站内容可信，也不能阻止用户主动提交信息给恶意网站。</p><p>遇到证书错误或域名拼写异常时应停止操作。</p>','published',NOW()),
('如何保护自己的在线账户','protect-online-accounts','如何保护自己的在线账户','用密码、验证、恢复信息和登录提醒建立账户安全防线。','<p>账户保护需要多个独立环节共同工作。</p><h2>四项基础措施</h2><p>使用独立密码、开启多重验证、保护恢复邮箱、打开登录通知并定期查看活动记录。</p><p>不使用的账户应关闭或删除，减少长期暴露面。</p>','published',NOW()),
('网络追踪技术是如何工作的','how-online-tracking-works','网络追踪技术是如何工作的？','了解 Cookie、像素和设备特征等常见追踪方式。','<p>网站和广告系统可能使用 Cookie、脚本、像素或设备特征来记录访问行为。</p><h2>减少追踪</h2><p>限制第三方 Cookie，清理不必要的站点数据，审慎授予通知和定位权限。</p><p>隐私工具可能影响网站功能，应根据场景逐项调整。</p>','published',NOW()),
('浏览器隐私设置指南','browser-privacy-settings','浏览器隐私设置指南：从基础选项开始','整理浏览器中的 Cookie、权限、同步和安全浏览设置。','<p>浏览器是接触互联网的主要入口，合理设置可以减少不必要的数据暴露。</p><h2>建议检查</h2><p>查看站点权限，限制第三方追踪，确认同步账户安全，并保持浏览器更新。</p><p>不要安装来源不明的扩展；定期删除不再使用的扩展。</p>','published',NOW()),
('什么是 IP 地址','what-is-ip-address','什么是 IP 地址？公网与内网的区别','解释 IP 地址的作用、类型以及它与在线隐私的关系。','<p>IP 地址用于在网络中标识连接端点。家庭网络通常同时涉及路由器的公网地址和设备的内网地址。</p><h2>它能说明什么</h2><p>IP 地址可以提供粗略的网络和地区信息，但通常不能单独证明一个人的真实身份。</p><p>不要把 IP 地址与完整匿名性简单等同。</p>','published',NOW()),
('DNS 服务器的工作原理','how-dns-servers-work','DNS 服务器的工作原理','从域名查询到缓存，理解 DNS 如何帮助打开网站。','<p>DNS 把便于记忆的域名转换为服务器地址。查询可能经过本地缓存、递归解析器和权威服务器。</p><h2>为什么会失败</h2><p>缓存过期、服务器故障、配置错误或网络限制都可能导致解析异常。</p><p>更换 DNS 前应了解服务商的隐私政策和稳定性。</p>','published',NOW()),
('如何识别恶意网站','identify-malicious-websites','如何识别恶意网站？','从地址、内容、证书和行为识别可疑网站。','<p>恶意网站不一定看起来粗糙，判断时要综合多个信号。</p><h2>重点观察</h2><p>检查域名拼写、异常弹窗、强制下载、证书警告和要求提供敏感信息的页面。</p><p>通过官方书签或手动输入地址访问重要服务。</p>','published',NOW()),
('如何保护个人数字身份','protect-digital-identity','如何保护个人数字身份','减少身份信息暴露并保护与身份相关的账户。','<p>数字身份由账户、联系方式、设备和公开信息共同构成。</p><h2>减少关联</h2><p>不同场景使用合适的公开信息，避免把邮箱、手机号和生日同时公开。</p><h2>保护恢复渠道</h2><p>恢复邮箱、手机号和验证器是账户安全的关键，应单独加强保护。</p>','published',NOW()),
('什么是零信任安全架构','zero-trust-security','什么是零信任安全架构？','用通俗语言解释零信任的验证、最小权限和持续检查原则。','<p>零信任不是某个单一产品，而是一种不因网络位置而默认信任的安全思路。</p><h2>核心原则</h2><p>验证访问者和设备，授予完成任务所需的最小权限，并持续检查访问状态。</p><p>个人用户也可以通过关闭不必要权限和定期复核会话实践这些原则。</p>','published',NOW()),
('什么是 WireGuard 协议','what-is-wireguard','什么是 WireGuard 协议？','介绍 WireGuard 的设计目标、密钥和使用时应注意的事项。','<p>WireGuard 是一种现代 VPN 协议，强调简洁的实现和基于密钥的身份验证。</p><h2>使用前要了解</h2><p>协议本身不决定服务商是否记录数据，也不保证所有网络环境都能连接。</p><p>配置文件包含敏感密钥，应像密码一样保存。</p>','published',NOW()),
('什么是 VLESS 协议','what-is-vless','什么是 VLESS 协议？基础概念与安全边界','介绍 VLESS 的基本定位，并提醒读者区分协议与整体服务安全。','<p>VLESS 是代理生态中使用的一种协议名称。理解它时，需要同时关注传输方式、身份验证、客户端来源和服务器管理。</p><h2>不要只看协议名称</h2><p>协议名称不能单独证明连接安全或服务可信。应阅读项目文档并使用合法、受支持的软件。</p>','published',NOW()),
('什么是网络流量加密','network-traffic-encryption','什么是网络流量加密？','理解传输中数据加密、端点安全和元数据之间的区别。','<p>网络流量加密用于降低传输内容被直接读取的风险。不同协议的保护范围和密钥管理方式不同。</p><h2>内容与元数据</h2><p>即使内容加密，连接时间、流量大小或目标域名等元数据也可能仍然可见。</p><p>安全需要加密、更新、权限控制和谨慎操作共同完成。</p>','published',NOW()),
('如何选择可靠的隐私保护工具','choose-privacy-tools','如何选择可靠的隐私保护工具','从透明度、更新、权限、商业模式和退出机制评估隐私工具。','<p>隐私工具不是越多越好。选择时应明确自己的问题，再审查工具的来源和权限。</p><h2>评估清单</h2><p>查看官方文档、更新记录、隐私政策、权限范围和支持渠道。避免使用承诺“绝对匿名”的宣传。</p><p>重要数据场景应先进行小范围测试并保留备份。</p>','published',NOW()),
('常见网络安全误区','common-cybersecurity-myths','常见网络安全误区：哪些说法不准确','澄清“有密码就安全”“HTTPS 等于可信”等常见网络安全误区。','<p>网络安全没有一次设置永久有效的方案，很多风险来自错误的安全感。</p><h2>三个常见误区</h2><p>复杂密码不能替代多重验证；HTTPS 不等于网站内容可信；安装安全软件也不能替代更新和谨慎操作。</p><p>建立分层防护并持续复盘，比追求单一工具更实际。</p>','published',NOW());
INSERT INTO article_category(article_id,category_id) SELECT a.id, CASE WHEN a.slug IN ('protect-online-privacy','public-wifi-safety','prevent-personal-data-leaks','what-is-end-to-end-encryption','why-data-encryption-matters','how-online-tracking-works','browser-privacy-settings','choose-privacy-tools') THEN 2 WHEN a.slug IN ('create-strong-passwords','two-factor-authentication-guide','protect-online-accounts','protect-digital-identity') THEN 3 WHEN a.slug IN ('what-is-vpn','vpn-vs-proxy','what-is-dns-leak','what-is-wireguard','what-is-vless','network-traffic-encryption') THEN 6 WHEN a.slug IN ('windows-network-security-settings','safe-public-network-use','what-is-https','what-is-ip-address','how-dns-servers-work') THEN 5 ELSE 1 END FROM articles a;
